hooks.command:
python3 -I -c "import sys; exec('status = 2
try:
 import pathlib, runpy, subprocess
 root = pathlib.Path(subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True, stderr=subprocess.PIPE, timeout=10).strip()).resolve(strict=True)
 entry = root / 'scripts' / 'guard_entry.py'
 if entry.resolve(strict=True) != entry:
  raise ValueError('guard entry resolves outside selected checkout')
 namespace = runpy.run_path(str(entry), run_name='_gamecreater_guard_entry')
 result = namespace['main']()
 if type(result) is not int:
  raise ValueError('guard entry returned invalid status')
 status = 0 if result == 0 else 2
except BaseException as error:
 try:
  print('guard-wrapper failed closed: ' + type(error).__name__, file=sys.stderr)
 except BaseException:
  pass
sys.exit(status)')"

